INSERT INTO teaching_mock_ready SELECT q.id FROM mock_exam_bank q JOIN teaching_mock_proposal p ON p.id=q.id WHERE BINARY CAST(JSON_OBJECT('id',q.id,'sourceType',q.source_type,'paperType',q.paper_type,'kind',q.kind,'subject',q.subject,'difficulty',q.difficulty,'stem',q.stem,'options',q.options_json,'answer',q.reference_answer,'explanation',q.explanation,'sourceLabel',q.source_label,'sourceUrl',q.source_url,'readingUrl',q.reading_url) AS CHAR)=BINARY CAST(p.before_content AS CHAR) FOR UPDATE;
INSERT INTO mock_exam_content_revision (revision_key,question_id,before_content,after_content,evidence_urls) SELECT p.revision_key,p.id,p.before_content,p.after_content,p.evidence_urls FROM teaching_mock_proposal p JOIN teaching_mock_ready t ON t.id=p.id ON DUPLICATE KEY UPDATE revision_key=mock_exam_content_revision.revision_key;
UPDATE mock_exam_bank q JOIN teaching_mock_proposal p ON p.id=q.id JOIN teaching_mock_ready t ON t.id=q.id JOIN mock_exam_content_revision r ON r.revision_key=p.revision_key SET q.stem=JSON_UNQUOTE(JSON_EXTRACT(p.after_content,'$.stem')),q.reference_answer=JSON_UNQUOTE(JSON_EXTRACT(p.after_content,'$.answer')),q.explanation=JSON_UNQUOTE(JSON_EXTRACT(p.after_content,'$.explanation')) WHERE BINARY CAST(JSON_OBJECT('id',q.id,'sourceType',q.source_type,'paperType',q.paper_type,'kind',q.kind,'subject',q.subject,'difficulty',q.difficulty,'stem',q.stem,'options',q.options_json,'answer',q.reference_answer,'explanation',q.explanation,'sourceLabel',q.source_label,'sourceUrl',q.source_url,'readingUrl',q.reading_url) AS CHAR)=BINARY CAST(p.before_content AS CHAR) AND r.question_id=p.id AND BINARY CAST(r.before_content AS CHAR)=BINARY CAST(p.before_content AS CHAR) AND BINARY CAST(r.after_content AS CHAR)=BINARY CAST(p.after_content AS CHAR) AND BINARY CAST(r.evidence_urls AS CHAR)=BINARY CAST(p.evidence_urls AS CHAR);
UPDATE mock_exam_content_revision r JOIN teaching_mock_proposal p ON p.revision_key=r.revision_key JOIN mock_exam_bank q ON q.id=p.id SET r.applied_at=COALESCE(r.applied_at,NOW()) WHERE r.question_id=p.id AND BINARY CAST(r.before_content AS CHAR)=BINARY CAST(p.before_content AS CHAR) AND BINARY CAST(r.after_content AS CHAR)=BINARY CAST(p.after_content AS CHAR) AND BINARY CAST(r.evidence_urls AS CHAR)=BINARY CAST(p.evidence_urls AS CHAR) AND BINARY CAST(JSON_OBJECT('id',q.id,'sourceType',q.source_type,'paperType',q.paper_type,'kind',q.kind,'subject',q.subject,'difficulty',q.difficulty,'stem',q.stem,'options',q.options_json,'answer',q.reference_answer,'explanation',q.explanation,'sourceLabel',q.source_label,'sourceUrl',q.source_url,'readingUrl',q.reading_url) AS CHAR)=BINARY CAST(p.after_content AS CHAR);
COMMIT;
SELECT JSON_OBJECT('target',CONCAT('question:',p.id),'id',p.id,'table','question','status',CASE WHEN q.id IS NULL THEN 'MISSING_TARGET' WHEN r.revision_key IS NOT NULL AND NOT (r.question_id=p.id AND BINARY CAST(r.before_content AS CHAR)=BINARY CAST(p.before_content AS CHAR) AND BINARY CAST(r.after_content AS CHAR)=BINARY CAST(p.after_content AS CHAR) AND BINARY CAST(r.evidence_urls AS CHAR)=BINARY CAST(p.evidence_urls AS CHAR)) THEN 'ARCHIVE_CONFLICT' WHEN BINARY CAST(JSON_OBJECT('type',q.type,'stem',q.stem,'options',q.options,'answer',q.answer,'analysis',q.analysis,'category',q.category,'discipline',COALESCE(s.discipline,CASE TRIM(q.category) WHEN '刑法' THEN '刑法' WHEN '民法' THEN '民商法' WHEN '行政法' THEN '宪法与行政法' ELSE '综合与待判定' END),'subject',COALESCE(s.subject,CASE TRIM(q.category) WHEN '刑法' THEN '刑法学' WHEN '民法' THEN '民法学' WHEN '行政法' THEN '行政法学' ELSE '待判定' END)) AS CHAR)=BINARY CAST(p.after_content AS CHAR) AND r.applied_at IS NOT NULL THEN 'APPLIED_OR_ALREADY_APPLIED' ELSE 'BASELINE_CHANGED' END) FROM teaching_question_proposal p LEFT JOIN question q ON q.id=p.id LEFT JOIN question_legal_subject s ON s.question_id=q.id LEFT JOIN question_content_revision r ON r.revision_key=p.revision_key ORDER BY p.id;
